   494  static void circular_memcpy(uint8_t* dst, uint8_t* window, const int mask,
   495          int64_t start, int64_t end)
   496  {
   497      if((start & mask) > (end & mask)) {
   498          ssize_t len1 = mask + 1 - (start & mask);
   499          ssize_t len2 = end & mask;
   500
   501          memcpy(dst, &window[start & mask], len1);
   502          memcpy(dst + len1, window, len2);
   503      } else {
   504          memcpy(dst, &window[start & mask], (size_t) (end - start));
   505      }
   506  }
